25	/**
26	 * Get a fingerprint for a working directory to use as a cache key.
27	 * Checks directory mtime and descendant file mtimes recursively.
28	 *
29	 * This allows for caching prompts that use the same working directory
30	 * when the files haven't changed.
31	 *
32	 * @param workingDir - Absolute path to the working directory
33	 * @returns SHA-256 hash fingerprint of the directory state
34	 * @throws Error if fingerprinting times out or directory is inaccessible
35	 */
36	export async function getWorkingDirFingerprint(workingDir: string): Promise<string> {
37	  const dirStat = fs.statSync(workingDir);
38	  const dirMtime = dirStat.mtimeMs;
39	
40	  const startTime = Date.now();
41	
42	  // Recursively get all files
43	  const getAllFiles = (dir: string, files: string[] = []): string[] => {
44	    if (Date.now() - startTime > FINGERPRINT_TIMEOUT_MS) {
45	      throw new Error('Working directory fingerprint timed out');
46	    }
47	
48	    const entries = fs.readdirSync(dir, { withFileTypes: true });
49	
50	    for (const entry of entries) {
51	      const fullPath = path.join(dir, entry.name);
52	      if (entry.isDirectory()) {
53	        getAllFiles(fullPath, files);
54	      } else if (entry.isFile()) {
55	        files.push(fullPath);
56	      }
57	    }
58	    return files;
59	  };
60	
61	  const allFiles = getAllFiles(workingDir);
62	
63	  // Create fingerprint from directory mtime + all file mtimes
64	  const fileMtimes = allFiles
65	    .map((file: string) => {
66	      const stat = fs.statSync(file);
67	      const relativePath = path.relative(workingDir, file);
68	      return `${relativePath}:${stat.mtimeMs}`;
69	    })
70	    .sort(); // Sort for consistent ordering
71	
72	  const fingerprintData = `dir:${dirMtime};files:${fileMtimes.join(',')}`;
73	  const fingerprint = crypto.createHash('sha256').update(fingerprintData).digest('hex');
74	
75	  return fingerprint;
76	}
